var authReset=function(n){function t(){n("form#form-reset-password").validate({rules:{password:{required:!0,minlength:6},confirmPassword:{required:!0,equalTo:"#password"}},messages:{password:{required:"Hãy nhập mật khẩu",minlength:"Mật khẩu ít nhất 6 kí tự"},confirmPassword:{required:"Hãy xác thực mật khẩu",equalTo:"Xác thực mật khẩu sai"}},submitHandler:function(t){n.ajax({url:"/Auth/ResetPassword",method:"POST",data:n(t).serialize(),success:function(i){if(i.isSuccessful)n(".reset-page").html("<h3>Đổi mật khẩu thành công<\/h3>");else n(t).find(".summary-eror").text(i.message)},error:function(n,t,i){console.log(t+": "+i)}})}})}function i(){t()}return{init:i}}(jQuery);$(document).ready(function(){authReset.init()});